(3367, 'UM OLHAR PARA AS ALTAS HABILIDADES CONSTRUINDO CAMINHOS', NULL, 1985, 916, 888, '87', '2008', '1', 'SÃO PAULO', NULL, NULL, 'livro', 1, 'logo.png', NULL, NULL, NULL, NULL, 1),
(3368, 'A ESCOLA QUE FAZ A DIFERENÇA, PROFESSORES QUE FAZEM A DIFERENÇA', NULL, 463, 834, 805, '0', '1997', '1', 'SÃO PAULO', '', '', NULL, 1, 'logo.png', '', NULL, NULL, NULL, 1),
(3369, 'A ESCOLA QUE FAZ A DIFERENÇA, PAIS QUE FAZEM A DIFERENÇA', NULL, 463, 834, 805, '0', '', '', '', '', '', NULL, 1, 'logo.png', '', NULL, NULL, NULL, 1),
(3370, 'JOGOS TEATRAIS NA ESCOLA: ATIVIDADES GLOBAIS DE EXPRESSÃO', NULL, 1879, 393, 840, '134', '2009', NULL, 'SÃO PAULO', '978-85-26276-35-2', NULL, 'livro', 1, 'img/capas_livros/1760472722_81wb7-QeL-L._SY342_.jpg', 'Ao desenvolver suas capacidades de expressão, a criança estará preparada para todo tipo de aprendizagem.\r\nCom esse objetivo, a autora reuniu aqui cinco grupos de atividades para explorar em sala de aula as capacidades de relacionamento, espontaneidade, imaginação, observação e percepção.\r\nEsta obra traz sugestões valiosas, que podem ser colocadas em prática não só nas aulas de Arte, mas também nas de Língua Portuguesa e História, por exemplo, como uma proposta inovadora de trabalhar conteúdos.', NULL, NULL, NULL, 1),
(3371, 'VARIAS FACES DA MATEMÁTICA', NULL, 1880, 43, 1084, '0', '2010', '2', 'SÃO PAULO', '978-85-21205-10-4', '', NULL, 1, 'logo.png', '', NULL, NULL, NULL, 1),
