(3671, 'MOVIMENTOS CULTURAIS DA JUVENTUDE', NULL, 2086, 155, 459, '0', '2004', '2', 'SAO PAULO', '851-60-40410', '', NULL, 1, 'logo.png', '', NULL, NULL, NULL, 1),
(3672, 'JOGOS EDUCATIVOS: ESTRUTURA E ORGANIZAÇÃO DA PRÁTICA', NULL, 2087, 321, 840, '96', '2009', '5ª', 'SÃO PAULO', '978-85-76552-28-4', NULL, 'livro', 1, 'img/capas_livros/1760472894_515UdC1BMoL._SY445_SX342_ML2_.jpg', 'Este livro sobre Jogos Educativos é parte integrante do Projeto Caravana do Esporte, iniciativa da ESPN BRASIL, que se constitui em 10 incursões de ação social pelo Norte, Nordeste e Centro-Oeste do Brasil, com o objetivo de estimular a prática do esporte com pressupostos educacionais e de inclusão social, em comunidades distantes e carentes, aliando os valores do esporte à educação, com intuito de despertar nos jovens à cidadania. Assim, realizando ações em conjunto com as escolas locais, envolvendo alunos, professores, funcionários, pais e toda a comunidade.', NULL, NULL, NULL, 1),
(3673, 'FOLCLORE BRASILEIRO: BAHIA', NULL, 2089, 1191, 939, '79', NULL, NULL, NULL, NULL, NULL, 'livro', 1, 'logo.png', NULL, NULL, NULL, NULL, 1),
