(4528, 'MUSA CAIPIRA AS ESTRAMBOTICAS AVENTURAS DO JOAQUIM BENTINHO', 'Português', 2626, 1159, NULL, '170', NULL, NULL, 'São Paulo', NULL, NULL, 'livro', 26, NULL, NULL, NULL, NULL, NULL, NULL),
(4529, 'CARREIRAS: Guia Ilustrado oara escolher a profissão certa', 'Português', 1531, 1122, 6, '320', '2024', '3ªedição', 'São Paulo', '978-85-396-4632-6', 'André Botelho, Carlos Szlak, Lana Lim', 'livro', 1, NULL, NULL, NULL, NULL, NULL, NULL),
(4530, 'Coração de Bicho (fábulas Modernas)', 'Português', NULL, NULL, 40, '104', '2021', '2a edição', 'Rio de Janeiro', '978-6599415333', NULL, 'livro', 1, 'img/capas_livros/1758918796_71cBMz4TYnL._SY425_.jpg', 'O livro \"Coração de Bicho - Fábulas Modernas\" da Escrita Fina, é uma obra encantadora que traz dez fábulas envolvendo animais que vivem emoções profundas, características humanas e situações do cotidiano. Escrito pela autora Angélica Lopes, o livro aborda temas como demandas familiares, pertencimento, hierarquia, empoderamento feminino e a finitude da vida de forma única e cativante.', NULL, NULL, NULL, NULL),
(4531, 'GRANDEZAS DO BRASIL NO TEMPO DE ANTONIL 1681 1716', 'Português', 1476, 1161, NULL, '80', '1996', '4 EDICAO', 'São Paulo', '85 7056 818 5', NULL, 'livro', 1, NULL, NULL, NULL, NULL, NULL, NULL),
